{  "explanation": "The sine graph is wavy because it is really circular motion viewed from the side. sin(θ) is just the vertical height of a point traveling around the unit circle: as the angle θ grows, that height climbs smoothly to 1, slides back through 0, dips to −1, and returns to 0. Every full turn repeats this same rise-and-fall, so the graph becomes an endless, smooth wave with period 2π. In the visualization, watch the yellow dot ride around the circle while its height is 'unwrapped' onto the graph — the wave is born from spinning.",  "manimCode": "// Title
const title = new Text({ text: 'Sine = height of a point on a spinning circle', color: WHITE, fontSize: 26 });
title.moveTo([0, 3.5, 0]);
await scene.play(new Write(title));

// Unit circle on the left (radius 1.5 world units)
const C = [-4.5, 0, 0];
const R = 1.5;
const circle = new Circle({ radius: R, color: BLUE_C });
circle.moveTo(C);

// Axes on the right. yLength 4.5 over yRange [-1.5, 1.5] gives 1.5 world units
// per data unit vertically, so graph heights exactly match the circle's heights.
const ax = new Axes({
  xRange: [0, 2 * Math.PI, Math.PI / 2],
  yRange: [-1.5, 1.5, 0.5],
  xLength: 8,
  yLength: 4.5,
  tips: false
});
ax.moveTo([2, 0, 0]);

await scene.play(new AnimationGroup([new Create(circle), new Create(ax)]));

// Faint guide showing the full target wave
const guide = ax.plot(x => Math.sin(x), { color: BLUE_E });
guide.setOpacity(0.3);
scene.add(guide);

const eq = new MathTex({ latex: 'y = \\sin(\\theta)' });
await eq.waitForRender();
eq.moveTo([4.8, 2.9, 0]);
scene.add(eq);

// Shared state
let angle = 0;
let traced = null;
let readout = null;
let animating = false;

function circlePoint(a) {
  return [C[0] + R * Math.cos(a), R * Math.sin(a), 0];
}

// Dynamic elements: dot on circle, dot on graph, radius, height, connector
const circleDot = new Dot({ point: circlePoint(0), color: YELLOW });
const traceDot = new Dot({ point: ax.c2p(0, 0), color: YELLOW });

const radiusLine = new Polygon({ vertices: [C, circlePoint(0)], color: WHITE });
radiusLine.setStrokeWidth(2).setFillOpacity(0);

const heightLine = new Polygon({ vertices: [[C[0] + R, 0, 0], circlePoint(0)], color: ORANGE });
heightLine.setStrokeWidth(4).setFillOpacity(0);

const connector = new Polygon({ vertices: [circlePoint(0), ax.c2p(0, 0)], color: GRAY });
connector.setStrokeWidth(1.5).setFillOpacity(0);

circleDot.addUpdater(() => circleDot.moveTo(circlePoint(angle)));
traceDot.addUpdater(() => traceDot.moveTo(ax.c2p(angle, Math.sin(angle))));
radiusLine.addUpdater(() => radiusLine.setVertices([C, circlePoint(angle)]));
heightLine.addUpdater(() => {
  const p = circlePoint(angle);
  heightLine.setVertices([[p[0], 0, 0], p]);
});
connector.addUpdater(() => {
  connector.setVertices([circlePoint(angle), ax.c2p(angle, Math.sin(angle))]);
});

scene.add(radiusLine, heightLine, connector, circleDot, traceDot);

// Traced portion of the wave (remove + re-plot pattern)
function updateTrace() {
  if (traced) { scene.remove(traced); traced = null; }
  if (angle > 0.02) {
    traced = ax.plot(x => Math.sin(x), { color: YELLOW, xRange: [0, angle] });
    scene.add(traced);
  }
}

// Numeric readout (Text is immutable: remove + recreate)
function updateReadout() {
  const s = 'theta = ' + angle.toFixed(2) + ',  sin = ' + Math.sin(angle).toFixed(2);
  if (readout) scene.remove(readout);
  readout = new Text({ text: s, color: WHITE, fontSize: 22 });
  readout.moveTo([-4.5, 2.6, 0]);
  scene.add(readout);
}
updateReadout();

// Intro: watch the wave being unwrapped from the circle
async function runTrace() {
  if (animating) return;
  animating = true;
  angle = 0;
  updateTrace();
  const steps = 90;
  for (let i = 1; i <= steps; i++) {
    angle = (i / steps) * 2 * Math.PI;
    updateTrace();
    if (i % 6 === 0) updateReadout();
    await scene.wait(0.045);
  }
  updateReadout();
  animating = false;
}
await runTrace();

// Interactivity: drag the dot around the circle
makeDraggable(circleDot, scene, { onDrag: (mob, pos) => {
  let a = Math.atan2(pos[1] - C[1], pos[0] - C[0]);
  if (a < 0) a += 2 * Math.PI;
  angle = a;
  updateTrace();
  updateReadout();
}});

const hint = new Text({ text: 'Drag the yellow dot around the circle', color: GRAY, fontSize: 20 });
hint.moveTo([-1.5, -3.4, 0]);
scene.add(hint);

const controls = new Controls(scene, { position: 'bottom-right' });
controls.addSlider({ label: 'theta', min: 0, max: 2 * Math.PI, value: 2 * Math.PI, step: 0.01, onChange: (v) => {
  angle = v;
  updateTrace();
  updateReadout();
}});
controls.addButton({ label: 'Replay trace', onClick: () => { runTrace(); }});

await scene.wait(999999);"}

